import { CampaignRepository } from "./campaign.repository";
import type {
  CampaignDefinitionInput,
  ScheduleDefinitionInput,
} from "./validations";

export class ListCampaignsQuery {
  constructor(private readonly repo: CampaignRepository) {}
  execute(data: {
    organizationId: string;
    type?: "TEMPLATE" | "CONCRETE";
    status?:
      | "DRAFT"
      | "PUBLISHED"
      | "SCHEDULED"
      | "PENDING_START"
      | "ACTIVE"
      | "PAUSED"
      | "COMPLETED"
      | "FAILED";
    search?: string;
    limit: number;
    offset: number;
  }) {
    const { organizationId, ...input } = data;
    return this.repo.listCampaigns(organizationId, input);
  }
}
export class GetCampaignQuery {
  constructor(private readonly repo: CampaignRepository) {}
  execute(data: { id: string; organizationId: string }) {
    return this.repo.getCampaign(data.id, data.organizationId);
  }
}
export class CreateCampaignCommand {
  constructor(private readonly repo: CampaignRepository) {}
  execute(
    data: CampaignDefinitionInput & {
      organizationId: string;
      createdById: string;
    },
  ) {
    const { organizationId, createdById, ...input } = data;
    return this.repo.createCampaign(
      organizationId,
      createdById,
      input as CampaignDefinitionInput,
    );
  }
}
export class UpdateCampaignCommand {
  constructor(private readonly repo: CampaignRepository) {}
  execute(data: {
    id: string;
    organizationId: string;
    data: CampaignDefinitionInput;
  }) {
    return this.repo.updateCampaign(data.id, data.organizationId, data.data);
  }
}
export class PublishCampaignCommand {
  constructor(private readonly repo: CampaignRepository) {}
  execute(data: { id: string; organizationId: string }) {
    return this.repo.publish(data.id, data.organizationId);
  }
