import { Container } from "@/src/server/container";
import {
  MessageBus,
  ListCampaignsQuery,
  GetCampaignQuery,
  CreateCampaignCommand,
  UpdateCampaignCommand,
  PublishCampaignCommand,
  CloneCampaignCommand,
  ListSchedulesQuery,
  GetScheduleQuery,
  CreateScheduleCommand,
  UpdateScheduleCommand,
  CancelScheduleCommand,
  PauseCampaignCommand,
  ResumeCampaignCommand,
  CompleteCampaignCommand,
  DuplicateScheduleCommand,
  ListCampaignsSchema,
  CampaignIdSchema,
  CreateCampaignSchema,
  UpdateCampaignSchema,
  CloneCampaignSchema,
  CampaignLifecycleSchema,
  ListSchedulesSchema,
  CreateScheduleSchema,
  UpdateScheduleSchema,
} from "@next-phish/backend";
import { toRouterPermissions } from "@next-phish/shared";
import { createPermissionProcedure, router } from "../../trpc/procedures";

const bus = Container.get(MessageBus);
const readProcedure = createPermissionProcedure(
  toRouterPermissions("campaigns", "read"),
);
const writeProcedure = createPermissionProcedure(
  toRouterPermissions("campaigns", "write"),
);

export const campaignRouter = router({
  list: readProcedure.input(ListCampaignsSchema).query(({ ctx, input }) =>
    bus.query(Container.get(ListCampaignsQuery), {
      ...input,
      organizationId: ctx.activeOrganizationId,
    }),
  ),
  getById: readProcedure.input(CampaignIdSchema).query(({ ctx, input }) =>
    bus.query(Container.get(GetCampaignQuery), {
      ...input,
      organizationId: ctx.activeOrganizationId,
    }),
  ),
  create: writeProcedure
    .input(CreateCampaignSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(CreateCampaignCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
        createdById: ctx.userId,
      }),
    ),
  update: writeProcedure
    .input(UpdateCampaignSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(UpdateCampaignCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
      }),
    ),
  publish: writeProcedure.input(CampaignIdSchema).mutation(({ ctx, input }) =>
    bus.dispatch(Container.get(PublishCampaignCommand), {
      ...input,
      organizationId: ctx.activeOrganizationId,
    }),
  ),
  clone: writeProcedure.input(CloneCampaignSchema).mutation(({ ctx, input }) =>
    bus.dispatch(Container.get(CloneCampaignCommand), {
      ...input,
      organizationId: ctx.activeOrganizationId,
      createdById: ctx.userId,
    }),
  ),
  pause: writeProcedure
    .input(CampaignLifecycleSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(PauseCampaignCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
      }),
    ),
  resume: writeProcedure
    .input(CampaignLifecycleSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(ResumeCampaignCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
      }),
    ),
  complete: writeProcedure
    .input(CampaignLifecycleSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(CompleteCampaignCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
      }),
    ),

  listSchedules: readProcedure
    .input(ListSchedulesSchema)
    .query(({ ctx, input }) =>
      bus.query(Container.get(ListSchedulesQuery), {
        ...input,
        organizationId: ctx.activeOrganizationId,
      }),
    ),
  getSchedule: readProcedure.input(CampaignIdSchema).query(({ ctx, input }) =>
    bus.query(Container.get(GetScheduleQuery), {
      ...input,
      organizationId: ctx.activeOrganizationId,
    }),
  ),
  createSchedule: writeProcedure
    .input(CreateScheduleSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(CreateScheduleCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
        createdById: ctx.userId,
      }),
    ),
  updateSchedule: writeProcedure
    .input(UpdateScheduleSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(UpdateScheduleCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
      }),
    ),
  cancelSchedule: writeProcedure
    .input(CampaignIdSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(CancelScheduleCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
      }),
    ),
  duplicateSchedule: writeProcedure
    .input(CampaignIdSchema)
    .mutation(({ ctx, input }) =>
      bus.dispatch(Container.get(DuplicateScheduleCommand), {
        ...input,
        organizationId: ctx.activeOrganizationId,
        createdById: ctx.userId,
      }),
    ),
});
import { z } from "zod";

function isIanaTimezone(value: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value }).format();
    return true;
  } catch {
    return false;
  }
}

const timezoneSchema = z
  .string()
  .trim()
  .min(1)
  .refine(isIanaTimezone, "A valid IANA timezone is required");

export const campaignTypeSchema = z.enum(["TEMPLATE", "CONCRETE"]);
export const campaignStatusSchema = z.enum([
  "DRAFT",
  "PUBLISHED",
  "SCHEDULED",
  "PENDING_START",
  "ACTIVE",
  "PAUSED",
  "COMPLETED",
  "FAILED",
]);

const campaignDefinitionSchema = z
  .object({
    name: z.string().trim().min(1).max(200),
    type: campaignTypeSchema,
    emailTemplateId: z.string().min(1),
    pageId: z.string().min(1),
    mailSendingProfileId: z.string().min(1),
    targetGroupId: z.string().min(1).nullable(),
    targetTimezone: timezoneSchema,
    autoCompleteAfterDays: z.number().int().positive().nullable().default(20),
  })
  .superRefine((value, ctx) => {
    if (value.type === "TEMPLATE" && value.targetGroupId !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["targetGroupId"],
        message: "Templates cannot select a target group",
      });
    }
    if (value.type === "CONCRETE" && value.targetGroupId === null) {
      ctx.addIssue({
        code: "custom",
        path: ["targetGroupId"],
        message: "Concrete campaigns require a target group",
      });
    }
  });

export const ListCampaignsSchema = z.object({
  type: campaignTypeSchema.optional(),
  status: campaignStatusSchema.optional(),
  search: z.string().trim().optional(),
  limit: z.number().int().min(1).max(100).default(50),
  offset: z.number().int().min(0).default(0),
});
export const CampaignIdSchema = z.object({ id: z.string().min(1) });
export const CreateCampaignSchema = campaignDefinitionSchema;
export const UpdateCampaignSchema = z.object({
  id: z.string().min(1),
  data: campaignDefinitionSchema,
});
export const CloneCampaignSchema = z
  .object({
    id: z.string().min(1),
    name: z.string().trim().min(1).max(200),
    type: campaignTypeSchema,
    targetGroupId: z.string().min(1).nullable(),
  })
  .superRefine((value, ctx) => {
    if (value.type === "TEMPLATE" && value.targetGroupId !== null)
      ctx.addIssue({
        code: "custom",
        path: ["targetGroupId"],
        message: "Templates cannot select a target group",
      });
    if (value.type === "CONCRETE" && value.targetGroupId === null)
      ctx.addIssue({
        code: "custom",
        path: ["targetGroupId"],
        message: "Concrete campaigns require a target group",
      });
  });

export const deliveryModeSchema = z.enum(["BLAST", "DRIP", "BATCH"]);
const scheduleDefinitionSchema = z
  .object({
    name: z.string().trim().min(1).max(200),
    type: z.enum(["ONE_TIME", "RECURRING"]),
    sourceCampaignIds: z.array(z.string().min(1)).min(1),
    targetGroupId: z.string().min(1).nullable(),
    targetTimezone: timezoneSchema,
    startsAt: z.coerce.date(),
    frequency: z
      .enum(["WEEKLY", "MONTHLY", "QUARTERLY", "HALF_YEARLY", "YEARLY"])
      .nullable()
      .default(null),
    localTimeMinutes: z
      .number()
      .int()
      .min(0)
      .max(1439)
      .nullable()
      .default(null),
    weekday: z.number().int().min(0).max(6).nullable().default(null),
    dayOfMonth: z.number().int().min(1).max(31).nullable().default(null),
    month: z.number().int().min(1).max(12).nullable().default(null),
    selectionStrategy: z.enum(["DECK", "RANDOM"]).nullable().default(null),
    shuffleDeck: z.boolean().default(false),
    deliveryMode: deliveryModeSchema,
    dripEmailsPerMinute: z.number().int().positive().nullable().default(null),
    batchSize: z.number().int().positive().nullable().default(null),
    batchIntervalMinutes: z.number().int().positive().nullable().default(null),
    maxCampaigns: z.number().int().positive().nullable().default(null),
    endsAt: z.coerce.date().nullable().default(null),
    autoCompleteAfterDays: z.number().int().positive().nullable().default(20),
  })
  .superRefine((value, ctx) => {
    if (value.type === "ONE_TIME") {
      if (value.sourceCampaignIds.length !== 1)
        ctx.addIssue({
          code: "custom",
          path: ["sourceCampaignIds"],
          message: "One-time schedules require exactly one source",
        });
      for (const field of [
        "frequency",
        "selectionStrategy",
        "localTimeMinutes",
        "weekday",
        "dayOfMonth",
        "month",
      ] as const) {
        if (value[field] !== null)
          ctx.addIssue({
            code: "custom",
            path: [field],
            message: `${field} is only valid for recurring schedules`,
          });
      }
    } else {
      if (!value.frequency || !value.selectionStrategy)
        ctx.addIssue({
          code: "custom",
          path: ["frequency"],
          message: "Recurring schedules require frequency and strategy",
        });
      if (value.localTimeMinutes === null)
        ctx.addIssue({
          code: "custom",
          path: ["localTimeMinutes"],
          message: "Recurring schedules require a local time",
        });
      if (value.frequency === "WEEKLY" && value.weekday === null)
        ctx.addIssue({
          code: "custom",
          path: ["weekday"],
          message: "Weekly schedules require a weekday",
        });
      if (
        value.frequency &&
        value.frequency !== "WEEKLY" &&
        value.dayOfMonth === null
      )
        ctx.addIssue({
          code: "custom",
          path: ["dayOfMonth"],
          message: "This frequency requires a day of month",
        });
      if (
        ["QUARTERLY", "HALF_YEARLY", "YEARLY"].includes(
          value.frequency ?? "",
        ) &&
        value.month === null
      )
        ctx.addIssue({
          code: "custom",
          path: ["month"],
          message: "This frequency requires a month",
        });
      if (value.frequency === "QUARTERLY" && (value.month ?? 0) > 3)
        ctx.addIssue({
          code: "custom",
          path: ["month"],
          message: "Quarterly month must be between 1 and 3",
        });
      if (value.frequency === "HALF_YEARLY" && (value.month ?? 0) > 6)
        ctx.addIssue({
          code: "custom",
          path: ["month"],
          message: "Half-yearly month must be between 1 and 6",
        });
    }
    if (value.deliveryMode === "BLAST") {
      if (value.dripEmailsPerMinute !== null)
        ctx.addIssue({
          code: "custom",
          path: ["dripEmailsPerMinute"],
          message: "Blast does not use a drip rate",
        });
      if (value.batchSize !== null || value.batchIntervalMinutes !== null)
        ctx.addIssue({
          code: "custom",
          path: ["batchSize"],
          message: "Blast does not use batch settings",
        });
    }
    if (value.deliveryMode === "DRIP") {
      if (!value.dripEmailsPerMinute)
        ctx.addIssue({
          code: "custom",
          path: ["dripEmailsPerMinute"],
          message: "Drip rate is required",
        });
      if (value.batchSize !== null || value.batchIntervalMinutes !== null)
        ctx.addIssue({
          code: "custom",
          path: ["batchSize"],
          message: "Drip does not use batch settings",
        });
    }
    if (value.deliveryMode === "BATCH") {
      if (!value.batchSize || !value.batchIntervalMinutes)
        ctx.addIssue({
          code: "custom",
          path: ["batchSize"],
          message: "Batch size and interval are required",
        });
      if (value.dripEmailsPerMinute !== null)
        ctx.addIssue({
          code: "custom",
          path: ["dripEmailsPerMinute"],
          message: "Batch does not use a drip rate",
        });
    }
    if (value.endsAt && value.endsAt <= value.startsAt)
      ctx.addIssue({
        code: "custom",
        path: ["endsAt"],
        message: "End date must follow start date",
      });
  });

export const ListSchedulesSchema = z.object({
  limit: z.number().int().min(1).max(100).default(50),
  offset: z.number().int().min(0).default(0),
});
export const CreateScheduleSchema = scheduleDefinitionSchema;
export const UpdateScheduleSchema = z.object({
  id: z.string().min(1),
  data: scheduleDefinitionSchema,
});
export const MaterializeOccurrenceSchema = z.object({
  scheduleId: z.string().min(1),
  sourceCampaignId: z.string().min(1),
  occurrenceAt: z.coerce.date(),
});

export const CampaignLifecycleSchema = z.object({ id: z.string().min(1) });

export type CampaignDefinitionInput = z.infer<typeof CreateCampaignSchema>;
export type ScheduleDefinitionInput = z.infer<typeof CreateScheduleSchema>;
import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import type { PrismaClient } from "@prisma/client";
import { CampaignRepository } from "../../src/campaign/campaign.repository";
import { EmailTemplateRepository } from "../../src/email-template/repositories/email-template.repository";
import { getFactories, getPrisma } from "../setup";

describe("CampaignRepository", () => {
  let db: PrismaClient;
  let repo: CampaignRepository;
  let organizationId: string;
  let userId: string;
  let refs: {
    emailTemplateId: string;
    pageId: string;
    mailSendingProfileId: string;
    targetGroupId: string;
  };

  beforeAll(() => {
    db = getPrisma();
    repo = new CampaignRepository(db);
  });
  beforeEach(async () => {
    const factories = getFactories();
    const user = await factories.user.createOne();
    const organization = await factories.organization.createOne();
    userId = user.id;
    organizationId = organization.id;
    const storedObject = await db.storedObject.create({
      data: {
        remoteId: `test/${crypto.randomUUID()}`,
        size: 10,
        format: "text/plain",
        organizationId,
      },
    });
    const file = await db.file.create({
      data: {
        storedObjectId: storedObject.id,
        name: "attachment.txt",
        size: 10,
        format: "text/plain",
        organizationId,
        uploadedById: userId,
      },
    });
    const email = await db.emailTemplate.create({
      data: {
        name: "Email",
        tags: [],
        html: "<p>Hello</p>",
        design: {},
        organizationId,
        createdById: userId,
        status: "ACTIVE",
        files: { create: { fileId: file.id } },
      },
    });
    const page = await db.page.create({
      data: {
        name: "Landing",
        html: "<h1>Hi</h1>",
        organizationId,
        createdById: userId,
        status: "ACTIVE",
      },
    });
    const profile = await db.mailSendingProfile.create({
      data: {
        organizationId,
        name: "SMTP",
        providerType: "SMTP",
        fromName: "Sender",
        fromEmail: "sender@example.test",
        providerConfig: {},
      },
    });
    const group = await db.targetGroup.create({
      data: {
        name: "Targets",
        organizationId,
        createdById: userId,
        status: "ACTIVE",
        users: {
          create: [
            {
              email: " User@Example.test ",
              normalizedEmail: "user@example.test",
              firstName: "A",
              lastName: "B",
            },
          ],
        },
      },
    });
    refs = {
      emailTemplateId: email.id,
      pageId: page.id,
      mailSendingProfileId: profile.id,
      targetGroupId: group.id,
    };
  });

  it("rejects cross-organization campaign resources", async () => {
    const other = await getFactories().organization.createOne();
    await expect(
      repo.createCampaign(other.id, userId, {
        name: "Invalid",
        type: "CONCRETE",
        ...refs,
        targetTimezone: "UTC",
        autoCompleteAfterDays: 20,
      }),
    ).rejects.toThrow(/organization/);
  });

  it("hides shadow templates from catalog repositories", async () => {
    await db.emailTemplate.create({
      data: {
        name: "Shadow",
        tags: [],
        html: "",
        design: {},
        organizationId,
        createdById: userId,
        visibility: "SHADOW",
        status: "ACTIVE",
      },
    });
    const result = await new EmailTemplateRepository(db).findByOrganizationId(
      organizationId,
      { limit: 50, offset: 0 },
    );
    expect(result.rows.map((row) => row.name)).toEqual(["Email"]);
  });

  it("materializes relational shadows and shares immutable attachment objects", async () => {
    const source = await repo.createCampaign(organizationId, userId, {
      name: "Template",
      type: "TEMPLATE",
      emailTemplateId: refs.emailTemplateId,
      pageId: refs.pageId,
      mailSendingProfileId: refs.mailSendingProfileId,
      targetGroupId: null,
      targetTimezone: "UTC",
      autoCompleteAfterDays: 20,
    });
    await repo.publish(source.id, organizationId);
    const { schedule } = await repo.createSchedule(organizationId, userId, {
      name: "One time",
      type: "ONE_TIME",
      sourceCampaignIds: [source.id],
      targetGroupId: refs.targetGroupId,
      targetTimezone: "UTC",
      startsAt: new Date("2030-01-01T12:00:00Z"),
      frequency: null,
      localTimeMinutes: null,
      weekday: null,
      dayOfMonth: null,
      month: null,
      selectionStrategy: null,
      shuffleDeck: false,
      deliveryMode: "BLAST",
      dripEmailsPerMinute: null,
      batchSize: null,
      batchIntervalMinutes: null,
      maxCampaigns: null,
      endsAt: null,
      autoCompleteAfterDays: 20,
    });
    const run = await repo.materializeOccurrence(
      schedule.id,
      source.id,
      new Date("2030-01-01T12:00:00Z"),
      organizationId,
      userId,
    );

    expect(run.status).toBe("SCHEDULED");
    expect(run.emailTemplate?.visibility).toBe("SHADOW");
    expect(run.targetGroup?.visibility).toBe("SHADOW");
    const files = await db.file.findMany({
      where: { shadowCampaignId: run.id },
    });
    const original = await db.emailTemplateFile.findFirstOrThrow({
      where: { emailTemplateId: refs.emailTemplateId },
      include: { file: true },
    });
    expect(files).toHaveLength(1);
    expect(files[0].storedObjectId).toBe(original.file.storedObjectId);
  });
});

