apps/next-app/src/components/organisms/campaigns/form-presentation.tsx
"use client";

import { ErrorMessage, Field, Form, useFormikContext } from "formik";
import { Button } from "primereact/button";
import { Dropdown } from "primereact/dropdown";
import { InputText } from "primereact/inputtext";
import { InputNumber } from "primereact/inputnumber";
import { InputSwitch } from "primereact/inputswitch";
import type {
  CampaignFormValues,
  EmailTemplateListItemView,
  PageListItemView,
} from "@next-phish/shared";
import { CatalogCard } from "@/src/components/molecules/catalog-card";
import { FormMessage } from "@/src/components/atoms/form-message";

interface Props {
  emailTemplates: EmailTemplateListItemView[];
  pages: PageListItemView[];
  sendingProfiles: Array<{ id: string; name: string }>;
  targetGroups: Array<{ id: string; name: string; usersCount?: number }>;
  error: string;
  onCancel: () => void;
}

const fieldClass =
  "w-full rounded-xl border border-white/10 bg-white/95 text-slate-900";

export function CampaignFormPresentation({
  emailTemplates,
  pages,
  sendingProfiles,
  targetGroups,
  error,
  onCancel,
}: Props) {
  const { values, setFieldValue, isSubmitting } =
    useFormikContext<CampaignFormValues>();
  return (
    <Form className="space-y-7">
      <div className="grid gap-4 md:grid-cols-2">
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Name</span>
          <Field as={InputText} name="name" className={fieldClass} />
          <ErrorMessage
            name="name"
            component="p"
            className="text-sm text-red-400"
          />
        </label>
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Campaign type</span>
          <Field
            as={Dropdown}
            name="type"
            options={[
              { label: "Template", value: "TEMPLATE" },
              { label: "Concrete campaign", value: "CONCRETE" },
            ]}
            className={fieldClass}
          />
        </label>
      </div>

      <section>
        <h2 className="mb-3 text-lg font-semibold text-white">
          Email template
        </h2>
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {emailTemplates.map((item) => (
            <CatalogCard
              key={item.id}
              {...item}
              selected={values.emailTemplateId === item.id}
              onSelect={(id) => setFieldValue("emailTemplateId", id)}
            />
          ))}
        </div>
        <ErrorMessage
          name="emailTemplateId"
          component="p"
          className="mt-2 text-sm text-red-400"
        />
      </section>

      <section>
        <h2 className="mb-3 text-lg font-semibold text-white">Landing page</h2>
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {pages.map((item) => (
            <CatalogCard
              key={item.id}
              {...item}
              selected={values.pageId === item.id}
              onSelect={(id) => setFieldValue("pageId", id)}
            />
          ))}
        </div>
        <ErrorMessage
          name="pageId"
          component="p"
          className="mt-2 text-sm text-red-400"
        />
      </section>

      <div className="grid gap-4 md:grid-cols-2">
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Sending profile</span>
          <Field
            as={Dropdown}
            name="mailSendingProfileId"
            options={sendingProfiles}
            optionLabel="name"
            optionValue="id"
            placeholder="Select a profile"
            className={fieldClass}
          />
          <ErrorMessage
            name="mailSendingProfileId"
            component="p"
            className="text-sm text-red-400"
          />
        </label>
        {values.type === "CONCRETE" ? (
          <label className="space-y-2 text-sm text-zinc-300">
            <span>Target group</span>
            <Field
              as={Dropdown}
