import { MultiSelect } from "primereact/multiselect";
import { Checkbox } from "primereact/checkbox";
import type { ScheduleFormValues } from "@next-phish/shared";
import { FormMessage } from "@/src/components/atoms/form-message";

interface Props {
  campaigns: Array<{ id: string; name: string; type: "TEMPLATE" | "CONCRETE" }>;
  targetGroups: Array<{ id: string; name: string; userCount: number }>;
  error: string;
  onCancel: () => void;
}
const fieldClass =
  "w-full rounded-xl border border-white/10 bg-white/95 text-slate-900";

export function ScheduleFormPresentation({
  campaigns,
  targetGroups,
  error,
  onCancel,
}: Props) {
  const { values, setFieldValue, isSubmitting } =
    useFormikContext<ScheduleFormValues>();
  const selectedGroup = targetGroups.find(
    (group) => group.id === values.targetGroupId,
  );
  const repeatingSources = campaigns.filter(
    (campaign) => campaign.type === "TEMPLATE",
  );
  return (
    <Form className="space-y-6">
      <div className="grid gap-4 md:grid-cols-2">
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Name</span>
          <Field as={InputText} name="name" className={fieldClass} />
          <ErrorMessage name="name" component="p" className="text-red-400" />
        </label>
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Schedule type</span>
          <Dropdown
            value={values.type}
            options={[
              { label: "One time", value: "ONE_TIME" },
              { label: "Repeating", value: "RECURRING" },
            ]}
            onChange={(event) => {
              void setFieldValue("type", event.value);
              void setFieldValue("sourceCampaignIds", []);
            }}
            className={fieldClass}
          />
        </label>
        <label className="space-y-2 text-sm text-zinc-300 md:col-span-2">
          <span>Campaign source</span>
          {values.type === "RECURRING" ? (
            <MultiSelect
              value={values.sourceCampaignIds}
              options={repeatingSources}
              optionLabel="name"
              optionValue="id"
              onChange={(event) =>
                void setFieldValue("sourceCampaignIds", event.value)
              }
              className={fieldClass}
              display="chip"
            />
          ) : (
            <Dropdown
              value={values.sourceCampaignIds[0] ?? null}
              options={campaigns}
              optionLabel="name"
              optionValue="id"
              onChange={(event) =>
                void setFieldValue("sourceCampaignIds", [event.value])
              }
              className={fieldClass}
            />
          )}
        </label>
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Target group</span>
          <Dropdown
            value={values.targetGroupId}
            options={targetGroups}
            optionLabel="name"
            optionValue="id"
            onChange={(event) => {
              void setFieldValue("targetGroupId", event.value);
              const group = targetGroups.find(
                (item) => item.id === event.value,
              );
              if (group && group.userCount > 600) {
                void setFieldValue("deliveryMode", "DRIP");
                void setFieldValue("dripEmailsPerMinute", 60);
                void setFieldValue("batchSize", null);
                void setFieldValue("batchIntervalMinutes", null);
              }
            }}
            placeholder="Inherited for a concrete source"
            className={fieldClass}
            showClear
          />
        </label>
        <label className="space-y-2 text-sm text-zinc-300">
          <span>Target timezone</span>
          <Field as={InputText} name="targetTimezone" className={fieldClass} />
        </label>
        <label className="space-y-2 text-sm text-zinc-300">
          <span>First occurrence</span>
          <Field
            as={InputText}
            type="datetime-local"
            name="startsAt"
            className={fieldClass}
          />
        </label>
      </div>
      {selectedGroup && selectedGroup.userCount > 600 ? (
        <FormMessage variant="success">
          For {selectedGroup.userCount} recipients, Drip at 60 emails/minute is
          recommended and remains configurable.
        </FormMessage>
      ) : null}

      {values.type === "RECURRING" ? (
        <section className="grid gap-4 rounded-xl border border-white/10 p-4 md:grid-cols-3">
          <label className="space-y-2 text-sm text-zinc-300">
            <span>Frequency</span>
            <Dropdown
              value={values.frequency}
              options={[
                "WEEKLY",
                "MONTHLY",
                "QUARTERLY",
                "HALF_YEARLY",
                "YEARLY",
              ].map((value) => ({ label: value.replaceAll("_", " "), value }))}
              onChange={(event) => void setFieldValue("frequency", event.value)}
              className={fieldClass}
            />
          </label>
          <label className="space-y-2 text-sm text-zinc-300">
            <span>Strategy</span>
            <Dropdown
              value={values.selectionStrategy}
              options={[
                { label: "Deck", value: "DECK" },
                { label: "Random", value: "RANDOM" },
              ]}
              onChange={(event) =>
                void setFieldValue("selectionStrategy", event.value)
              }
              className={fieldClass}
            />
          </label>
          <label className="space-y-2 text-sm text-zinc-300">
            <span>Local time (minutes after midnight)</span>
            <InputNumber
              value={values.localTimeMinutes}
              min={0}
              max={1439}
              onValueChange={(event) =>
                void setFieldValue("localTimeMinutes", event.value ?? null)
              }
              className="w-full"
            />
          </label>
          {values.frequency === "WEEKLY" ? (
            <label className="space-y-2 text-sm text-zinc-300">
              <span>Weekday</span>
              <InputNumber
                value={values.weekday}
                min={0}
                max={6}
                onValueChange={(event) =>
                  void setFieldValue("weekday", event.value ?? null)
                }
                className="w-full"
              />
            </label>
          ) : null}
          {values.frequency && values.frequency !== "WEEKLY" ? (
            <label className="space-y-2 text-sm text-zinc-300">
              <span>Day of month</span>
              <InputNumber
                value={values.dayOfMonth}
                min={1}
                max={31}
                onValueChange={(event) =>
                  void setFieldValue("dayOfMonth", event.value ?? null)
                }
                className="w-full"
              />
            </label>
          ) : null}
          {["QUARTERLY", "HALF_YEARLY", "YEARLY"].includes(
