"use client";

import { Formik } from "formik";
import { useRouter } from "next/navigation";
import {
  scheduleFormSchema,
  type ScheduleFormValues,
} from "@next-phish/shared";
import { trpc } from "@/src/lib/trpc";
import { useFormStatus } from "@/src/hooks/use-form-status";
import { toFormikValidation } from "@/src/lib/to-formik-validation";
import { ScheduleFormPresentation } from "./form-presentation";

export function ScheduleFormContainer({ campaignId }: { campaignId?: string }) {
  const router = useRouter();
  const { status, setError, reset } = useFormStatus();
  const campaigns = trpc.campaign.list.useQuery({
    status: "PUBLISHED",
    limit: 100,
    offset: 0,
  });
  const groups = trpc.targetGroup.list.useQuery({
    limit: 100,
    offset: 0,
    filters: { status: "ACTIVE" },
  });
  const create = trpc.campaign.createSchedule.useMutation();
  const initialValues: ScheduleFormValues = {
    name: "",
    type: "ONE_TIME",
    sourceCampaignIds: campaignId ? [campaignId] : [],
    targetGroupId: null,
    targetTimezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    startsAt: "",
    frequency: null,
    localTimeMinutes: null,
    weekday: null,
    dayOfMonth: null,
    month: null,
    selectionStrategy: null,
    shuffleDeck: false,
    deliveryMode: "BLAST",
    dripEmailsPerMinute: null,
    batchSize: null,
    batchIntervalMinutes: null,
    maxCampaigns: null,
    endsAt: null,
    autoCompleteAfterDays: 20,
  };
  async function submit(values: ScheduleFormValues) {
    reset();
    try {
      const recurring = values.type === "RECURRING";
      const result = await create.mutateAsync({
        ...values,
        startsAt: new Date(values.startsAt),
        endsAt: values.endsAt ? new Date(values.endsAt) : null,
        frequency: recurring ? values.frequency : null,
        selectionStrategy: recurring ? values.selectionStrategy : null,
        localTimeMinutes: recurring ? values.localTimeMinutes : null,
        weekday: recurring ? values.weekday : null,
        dayOfMonth: recurring ? values.dayOfMonth : null,
        month: recurring ? values.month : null,
        shuffleDeck: recurring ? values.shuffleDeck : false,
      });
      router.push(`/schedule/${result.schedule.id}`);
    } catch (error) {
      setError(
        error instanceof Error ? error.message : "Schedule could not be saved",
      );
    }
  }
  return (
    <div className="px-6 py-8">
      <h1 className="text-2xl font-semibold text-white">Create schedule</h1>
      <p className="mb-7 mt-1 text-sm text-zinc-400">
        Configure timing and delivery. Sending remains deferred.
      </p>
      <Formik
        initialValues={initialValues}
        validate={toFormikValidation(scheduleFormSchema)}
        onSubmit={submit}
      >
        <ScheduleFormPresentation
          campaigns={(campaigns.data?.rows ?? []).map(({ id, name, type }) => ({
            id,
            name,
            type,
          }))}
          targetGroups={groups.data?.targetGroups ?? []}
          error={status.type === "error" ? status.message : ""}
          onCancel={() => router.push("/schedule")}
        />
      </Formik>
    </div>
  );
}

