 17	function sanitizeHtml(html: string): string {
 18	  let rendered = html;
 19	  for (const [token, value] of Object.entries(DUMMY_VALUES))
 20	    rendered = rendered.split(token).join(value);
 21	
 22	  const document = new DOMParser().parseFromString(rendered, "text/html");
 23	  document
 24	    .querySelectorAll(
 25	      "script,iframe,object,embed,form,input,button,textarea,select,link,meta,base",
 26	    )
