 58	function blobToBase64(blob: Blob): Promise<string> {
 59	  return new Promise((resolve, reject) => {
 60	    const reader = new FileReader();
 61	    reader.onerror = () => reject(reader.error);
 62	    reader.onload = () => resolve(String(reader.result).split(",")[1] ?? "");
 63	    reader.readAsDataURL(blob);
 64	  });
