  1	"use client";
  2	
  3	import { toCanvas } from "html-to-image";
  4	
  5	const WIDTH = 800;
  6	const HEIGHT = 600;
  7	const MAX_BYTES = 2 * 1024 * 1024;
  8	
  9	const DUMMY_VALUES: Record<string, string> = {
 10	  "{{.FirstName}}": "Alex",
 11	  "{{.LastName}}": "Morgan",
 12	  "{{.Email}}": "alex@example.invalid",
 13	  "{{.Position}}": "Team member",
 14	  "{{.URL}}": "https://example.invalid/training",
 15	};
 16	
 17	function sanitizeHtml(html: string): string {
 18	  let rendered = html;
 19	  for (const [token, value] of Object.entries(DUMMY_VALUES))
 20	    rendered = rendered.split(token).join(value);
 21	
 22	  const document = new DOMParser().parseFromString(rendered, "text/html");
 23	  document
 24	    .querySelectorAll(
 25	      "script,iframe,object,embed,form,input,button,textarea,select,link,meta,base",
 26	    )
 27	    .forEach((node) => node.remove());
 28	  for (const element of document.querySelectorAll("*")) {
 29	    for (const attribute of [...element.attributes]) {
 30	      const name = attribute.name.toLowerCase();
 31	      const value = attribute.value.trim().toLowerCase();
 32	      if (
 33	        name.startsWith("on") ||
 34	        ["srcdoc", "action", "formaction"].includes(name) ||
 35	        ((name === "src" || name === "href") &&
 36	          !value.startsWith("data:image/") &&
 37	          !value.startsWith("#"))
 38	      )
 39	        element.removeAttribute(attribute.name);
 40	      if (name === "style" && /url\s*\(/i.test(attribute.value))
 41	        element.removeAttribute("style");
 42	    }
 43	  }
 44	  return document.body.innerHTML;
 45	}
 46	
 47	function canvasBlob(canvas: HTMLCanvasElement): Promise<Blob> {
 48	  return new Promise((resolve, reject) => {
 49	    canvas.toBlob(
 50	      (blob) =>
 51	        blob ? resolve(blob) : reject(new Error("Preview encoding failed")),
 52	      "image/webp",
 53	      0.82,
 54	    );
 55	  });
 56	}
 57	
 58	function blobToBase64(blob: Blob): Promise<string> {
 59	  return new Promise((resolve, reject) => {
 60	    const reader = new FileReader();
 61	    reader.onerror = () => reject(reader.error);
 62	    reader.onload = () => resolve(String(reader.result).split(",")[1] ?? "");
 63	    reader.readAsDataURL(blob);
 64	  });
 65	}
 66	
 67	export async function createCatalogPreview(input: {
 68	  html: string;
 69	  upload: (data: {
 70	    resourceId: string;
 71	    sourceRevision: number;
 72	    format: "image/webp";
 73	    body: string;
 74	  }) => Promise<unknown>;
 75	  resourceId: string;
 76	  sourceRevision: number;
 77	}): Promise<void> {
 78	  const host = document.createElement("div");
 79	  host.setAttribute("aria-hidden", "true");
 80	  Object.assign(host.style, {
 81	    position: "fixed",
 82	    left: "-10000px",
 83	    top: "0",
 84	    width: `${WIDTH}px`,
 85	    height: `${HEIGHT}px`,
 86	    overflow: "hidden",
 87	    background: "white",
 88	    color: "black",
 89	    pointerEvents: "none",
 90	  });
 91	  host.innerHTML = sanitizeHtml(input.html);
 92	  document.body.appendChild(host);
 93	  try {
 94	    const canvas = await toCanvas(host, {
 95	      width: WIDTH,
 96	      height: HEIGHT,
 97	      canvasWidth: WIDTH,
 98	      canvasHeight: HEIGHT,
 99	      pixelRatio: 1,
100	      cacheBust: true,
101	      backgroundColor: "#ffffff",
102	    });
103	    const blob = await canvasBlob(canvas);
104	    if (blob.size > MAX_BYTES)
105	      throw new Error("Generated preview is too large");
106	    await input.upload({
107	      resourceId: input.resourceId,
108	      sourceRevision: input.sourceRevision,
109	      format: "image/webp",
110	      body: await blobToBase64(blob),
111	    });
112	  } finally {
113	    host.remove();
114	  }
115	}
